import React, { useState, useEffect } from "react";
import "./App.css";

// Function to sort tasks by date
const sortTasksByDueDate = (tasks) => {
  return tasks.slice().sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));
};

function App() {
  // State to store tasks
  const [tasks, setTasks] = useState([]);

  // Fetch Star Wars data on page load
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch("https://swapi.dev/api/people/"); // Star Wars API
        const data = await response.json();
        
        // Map Star Wars data to fit your app's task structure
        const starWarsTasks = data.results.map((character, index) => ({
          id: index + 1, // Assign unique IDs
          name: character.name,
          description: `A character from Star Wars with height ${character.height}cm and mass ${character.mass}kg.`,
          dueDate: "2024-12-31", // Add a placeholder date
        }));

        // Set tasks to include Star Wars characters
        setTasks(starWarsTasks);
      } catch (error) {
        console.error("Error fetching Star Wars API:", error);
      }
    };

    fetchData(); // Call the function
  }, []); // Empty dependency array ensures it runs only once on page load

  // Function for form submission handling
  const handleFormSubmit = (e) => {
    e.preventDefault();
    const taskName = e.target.taskName.value.trim();
    const taskDescription = e.target.taskDescription.value.trim();
    const taskDueDate = e.target.taskDueDate.value;

    if (!taskName || !taskDescription || !taskDueDate) {
      alert("All fields are required");
      return;
    }

    const newTask = {
      id: Date.now(),
      name: taskName,
      description: taskDescription,
      dueDate: taskDueDate,
    };

    setTasks((prevTasks) => [...prevTasks, newTask]);
    e.target.reset();
  };

  return (
    <div className="App">
      <h1>PyTasks</h1>
      <form onSubmit={handleFormSubmit}>
        <label>Task Name: <input type="text" name="taskName" /></label>
        <label>Description: <input type="text" name="taskDescription" /></label>
        <label>Due Date: <input type="date" name="taskDueDate" /></label>
        <button type="submit">Add Task</button>
      </form>

      <div className="task-list">
        {sortTasksByDueDate(tasks).map((task) => (
          <div key={task.id} className="task-item">
            <h3>{task.name}</h3>
            <p>{task.description}</p>
            <p><strong>Due:</strong> {task.dueDate}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
